CREATE TABLE orion_f02.motivos_03fac4 (
 cod_fila varchar(20) PRIMARY KEY,
 cod_evaluacion_experta varchar(20) NOT NULL,
 cod_propietario varchar(20) NOT NULL,
 orden integer NOT NULL CHECK(orden>=0),
 coleccion text NOT NULL,
 clave_tipo text NOT NULL CHECK(clave_tipo IN ('NULL','STRING','INT')),
 clave_texto text,
 CHECK((clave_tipo='NULL')=(clave_texto IS NULL)),
 contenido_presente boolean NOT NULL,
 contenido_tipo text NOT NULL,
 contenido_texto text,
 contenido_entero bigint,
 contenido_real_ieee754 char(16),
 contenido_logico boolean,
 UNIQUE(cod_evaluacion_experta,cod_fila),
 CHECK (contenido_tipo IN ('NULL','STRING','INT','FLOAT','BOOL')),
 CHECK (contenido_presente OR contenido_tipo='NULL'),
 CHECK ((contenido_tipo='NULL' AND num_nonnulls(contenido_texto,contenido_entero,contenido_real_ieee754,contenido_logico)=0) OR (contenido_tipo<>'NULL' AND num_nonnulls(contenido_texto,contenido_entero,contenido_real_ieee754,contenido_logico)=1 AND CASE contenido_tipo WHEN 'STRING' THEN contenido_texto IS NOT NULL WHEN 'INT' THEN contenido_entero IS NOT NULL WHEN 'FLOAT' THEN contenido_real_ieee754 ~ '^[a-f0-9]{16}$' WHEN 'BOOL' THEN contenido_logico IS NOT NULL ELSE false END))
