CREATE FUNCTION orion_f02.cerrar_evaluacion() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE fila record; cantidad bigint; primero bigint; ultimo bigint; entrada record;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'No se borra una evaluación' USING ERRCODE='55000'; END IF;
 IF OLD.estado<>'ABIERTA' OR NEW.estado<>'CERRADA' THEN RAISE EXCEPTION 'Transición de cierre inválida' USING ERRCODE='55000'; END IF;
 NEW.estado:='ABIERTA';
 IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'El cierre no reescribe la cabecera' USING ERRCODE='55000'; END IF;
 NEW.estado:='CERRADA';FOR fila IN SELECT cod_fila,instrumental_capturas_capturas_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.capturas_a87703 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='Ca877034852';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección capturas_a87703 incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_con_224bc4d292_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.contratos_relaciones_4f168a WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='C4f168aeb0b';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección contratos_relaciones_4f168a incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_b3e8a9143b_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_condiciones_regla_experta WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_condiciones_regla_experta incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_42f32615ef_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_consecuencias_regla_experta WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_consecuencias_regla_experta incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_65538363b1_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_criterios_dominios_resultado WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_criterios_dominios_resultado incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_d712a36b91_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_dominios_valores_expertos WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_dominios_valores_expertos incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_ae7bd93fc7_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_fuentes_datos_expertas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_fuentes_datos_expertas incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_cfa5292fd5_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_mapeos_valores_fuente WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_mapeos_valores_fuente incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,instrumental_conocimiento_tab_2968a98540_cantidad AS esperada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.copia_mapeos_variables_fuente WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='I';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección copia_mapeos_variables_fuente incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
