 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.soportes_027418 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='C027418f6cc';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección soportes_027418 incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,datos_originales_captura_orig_40f70870c5_cantidad AS esperada FROM orion_f02.soportes_027418 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.motivos_a33175 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='Ca33175a241';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección motivos_a33175 incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,datos_originales_captura_orig_2f6504d85f_cantidad AS esperada FROM orion_f02.soportes_027418 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.selectores_c9e61d WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='Cc9e61d6130';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección selectores_c9e61d incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,datos_originales_captura_orig_78f1a55d9d_cantidad AS esperada FROM orion_f02.soportes_027418 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.preguntas_declarativas_originales_52d856 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='C52d856d563';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección preguntas_declarativas_originales_52d856 incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,datos_originales_captura_orig_e392bbd0dd_cantidad AS esperada FROM orion_f02.soportes_027418 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.respuestas_originales_014dd1 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='C014dd1988b';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección respuestas_originales_014dd1 incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
FOR fila IN SELECT cod_fila,datos_originales_captura_orig_584101441a_cantidad AS esperada FROM orion_f02.soportes_027418 WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta LOOP
 SELECT count(*),min(orden),max(orden) INTO cantidad,primero,ultimo FROM orion_f02.vinculos_preguntas_actuales_7b4dbb WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND cod_propietario=fila.cod_fila AND coleccion='C7b4dbb2388';
 IF cantidad<>fila.esperada OR (cantidad>0 AND (primero<>0 OR ultimo<>cantidad-1)) THEN RAISE EXCEPTION 'Colección vinculos_preguntas_actuales_7b4dbb incompleta o discontinua' USING ERRCODE='23514'; END IF; END LOOP;
SELECT * INTO entrada FROM orion_f02.entradas_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta;
 IF NOT FOUND THEN RAISE EXCEPTION 'Faltan entradas' USING ERRCODE='23514'; END IF;
IF entrada.instrumental_contexto_residente_texto IS DISTINCT FROM NEW.cod_residente THEN RAISE EXCEPTION 'Contexto residente cruzado' USING ERRCODE='23514'; END IF;
IF entrada.instrumental_contexto_usuario_ejecucion_texto IS DISTINCT FROM NEW.cod_usuario_ejecucion THEN RAISE EXCEPTION 'Contexto usuario_ejecucion cruzado' USING ERRCODE='23514'; END IF;
IF entrada.instrumental_contexto_evaluacion_texto IS DISTINCT FROM NEW.id_evaluacion_dominio THEN RAISE EXCEPTION 'Contexto evaluacion cruzado' USING ERRCODE='23514'; END IF;
IF entrada.petersen_contexto_residente_texto IS DISTINCT FROM NEW.cod_residente THEN RAISE EXCEPTION 'Contexto residente cruzado' USING ERRCODE='23514'; END IF;
IF entrada.petersen_contexto_usuario_ejecucion_texto IS DISTINCT FROM NEW.cod_usuario_ejecucion THEN RAISE EXCEPTION 'Contexto usuario_ejecucion cruzado' USING ERRCODE='23514'; END IF;
IF entrada.petersen_contexto_evaluacion_texto IS DISTINCT FROM NEW.id_evaluacion_petersen THEN RAISE EXCEPTION 'Contexto evaluacion cruzado' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_nodos_semanticos k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en nodos_semanticos' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_relaciones_semanticas k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en relaciones_semanticas' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_dominios_valores_expertos k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en dominios_valores_expertos' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_variables_expertas k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en variables_expertas' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_fuentes_datos_expertas k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en fuentes_datos_expertas' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_mapeos_variables_fuente k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en mapeos_variables_fuente' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT 1 FROM orion_f02.copia_reglas_expertas k WHERE k.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND (NOT k.cod_version_modelo_presente OR k.cod_version_modelo_tipo<>'STRING' OR k.cod_version_modelo_texto IS DISTINCT FROM CASE k.coleccion WHEN 'I' THEN entrada.instrumental_conocimiento_version_texto WHEN 'P' THEN entrada.petersen_gobierno_conocimiento_version_texto END)) THEN RAISE EXCEPTION 'Versión cruzada en reglas_expertas' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM orion_f02.copia_condiciones_regla_experta c WHERE c.cod_evaluacion_experta=NEW.cod_evaluacion_experta AND NOT EXISTS(
  SELECT 1 FROM orion_f02.anclajes_condiciones_adquiridas a WHERE a.cod_evaluacion_experta=c.cod_evaluacion_experta AND a.rama=c.coleccion AND a.cod_condicion_regla=c.cod_condicion_regla_texto AND a.cod_regla_experta=c.cod_regla_experta_texto))
 THEN RAISE EXCEPTION 'Falta anclaje de condición adquirida' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER cierre_inmutable BEFORE UPDATE OR DELETE ON orion_f02.evaluaciones_compuestas FOR EACH ROW EXECUTE FUNCTION orion_f02.cerrar_evaluacion();
CREATE FUNCTION orion_f02.exigir_cierre() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM orion_f02.evaluaciones_compuestas WHERE cod_evaluacion_experta=NEW.cod_evaluacion_experta AND estado<>'CERRADA') THEN
  RAISE EXCEPTION 'No se confirma una evaluación parcial' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER confirma_completo AFTER INSERT OR UPDATE ON orion_f02.evaluaciones_compuestas DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION orion_f02.exigir_cierre();
CREATE TRIGGER sin_truncate BEFORE TRUNCATE ON orion_f02.evaluaciones_compuestas FOR EACH STATEMENT EXECUTE FUNCTION orion_f02.inmutable();
CREATE TRIGGER sin_truncate BEFORE TRUNCATE ON orion_f02.releases_motor FOR EACH STATEMENT EXECUTE FUNCTION orion_f02.inmutable();